INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66433657', 66433657, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Jasa Konsultan National Programme Manager (NPM)  Kegiatan Program Kerja Sama Pemerintah RI dan UNFPA Siklus 11 (2026-2030)  TA 2026', 'Jasa Konsultansi', 'Seleksi', 'DKI Jakarta, Jakarta Pusat (Kota)', 310000000, 'March 2026', 'Lainnya', 1, 1, '12 Bulan', 'Keluaran dalam fungsi koordinasi teknis Bappenas sebagai Ketua Tim Teknis Kerjasama: 1. Koordinasi penyusunan Dokumen perencanaan kerja sama (CPD, CPAP, Pedum, AWP) yang selaras dengan prioritas pembangunan nasional. 2. Pengawalan penyusunan Programme Document Hibah RI-UNICEF di lintas K/L 3. Penyusunan Laporan pemantauan pelaksanaan kerjasama tiap semester 4. Komunikasi dengan pihak UNICEF dan K/L pelaksana dalam pengendalian pelaksanaan kerjasama RI-UNICEF 5. Pelaksanaan, pemantauan, dan pengendalian program berjalan terstruktur melalui mekanisme rapat Tim Pengarah, Tim Teknis, Pokja Tematik, Annual Review,', '1. Pendidikan Master/Sarjana Strata 2 (S2) bidang kesehatan masyarakat, sosial, kebijakan publik, atau pembangunan; 2. Berpengalaman minimum 10 tahun di bidang kesehatan/kesehatan reproduksi/gender/kependudukan di Indonesia dan lebih disukai memiliki pengalaman bekerja di instansi pemerintah dan/atau proyek pemerintah, yang dapat dibuktikan dengan referensi kerja; 3. Memiliki pengalaman dalam mengelola/manajemen proyek di tingkat nasional, yang dapat dibuktikan dengan referensi kerja; 4. Memiliki pengalaman dalam mengelola sumber daya manusia, dan memiliki kemampuan bekerja dalam tim dan lingkungan multi culture; 5. Berpengalaman bekerja dengan lembaga pemerintah dan organisasi donor/mitra pembangunan internasional, yang dapat dibuktikan dengan referensi kerja; 6. Memahami isu-isu bidang kesehatan, kesehatan reproduksi, gender, dan/atau kependudukan, dibuktikan dengan (a) contoh laporan/jurnal/karya tulis yang pernah dibuat; atau (b) keterlibatan dalam penyusunan dokumen perencanaan pembangunan seperti Stranas, Rencana Aksi Nasional, Background Study; atau (c) keterlibatan dalam penyusunan dokumen kerja sama seperti Country Programme Document (CPD), Country Programme Implementation Plan (CPIP), atau dokumen kerja sama luar negeri lainnya; 7. Mampu berbahasa Inggris secara lisan dan tulisan dibuktikan dengan (a) TOEFL/TOEIC/IELTS (550/690/6,5) atau sertifikat yang masih berlaku; atau (b) memiliki ijazah S2 luar negeri; atau (c) menunjukkan hasil tulisan dalam Bahasa Inggris; dan 8. Memiliki kemampuan berkomunikasi dan kerja sama tim yang baik.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2761217);
