INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66469282', 66469282, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'Jasa Konsultansi Perorangan Penyusunan Tinjauan Hukum dan Pendampingan Kepatuhan dalam Pelaksanaan Manajemen Risiko Organisasi di Lingkungan Kementerian PPN/Bappenas', 'Jasa Konsultansi', 'Seleksi', 'DKI Jakarta, Jakarta Selatan (Kota)', 112500000, 'March 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1', 'Maksud Pekerjaan: Menyediakan dukungan teknis dan substantif aspek hukum guna memperkuat manajemen risiko di Kementerian PPN/Bappenas. Melalui tinjauan hukum, penjelasan regulasi, dan pengelolaan informasi hukum, pekerjaan ini membantu Bagian Manajemen Risiko dalam penyusunan, pemantauan, serta pengendalian internal tanpa mengambil alih kewenangan unit kerja. Tujuan Pelaksanaan: 1. Memastikan pemahaman hukum memadai agar manajemen risiko selaras perundang-undangan. 2. Identifikasi isu hukum untuk minimalkan potensi ketidaksesuaian regulasi. 3. Penjelasan hukum atas dokumen dan kegiatan selama siklus manajemen risiko. 4. Penguatan kontrol internal melalui peninjauan kepatuhan hukum yang ketat. 5. Menjamin ketersediaan dokumentasi hukum sebagai referensi manajemen risiko.', 'Keluaran dari kegiatan ini berupa terselenggaranya Penyusunan Tinjauan Hukum dan Pendampingan Kepatuhan dalam Pelaksanaan Manajemen Risiko Organisasi yang didokumentasikan dalam bentuk laporan termin dan laporan akhir, serta didukung oleh dokumentasi hasil kerja berupa kompilasi regulasi, catatan tinjauan hukum, dan bahan pendukung lain yang relevan. Keluaran tersebut dinyatakan diterima setelah memperoleh persetujuan dari Bagian Manajemen Risiko.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2761602);
