INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66473847', 66473847, 'analyze_legacy', 'Kementerian Hak Asasi Manusia', 'central', 'KANTOR WILAYAH KALIMANTAN TIMUR', 'Pengadaan Sewa Gedung Kantor Wilayah Kalimantan Timur', 'Jasa Lainnya', 'Dikecualikan', 'Kalimantan Timur, Samarinda (Kota)', 901041000, 'March 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Tahun', 'Dalam rangka mendukung kelancaran pelaksanaan tugas dan fungsi Kantor Wilayah Kementerian Hak Asasi Manusia Kalimantan Timur, diperlukan sarana dan prasarana perkantoran yang memadai, representatif, serta mampu menunjang kegiatan administrasi pemerintahan dan pelayanan kepada masyarakat. Sehubungan dengan kebutuhan tersebut, diperlukan penyediaan jasa sewa gedung kantor yang dapat digunakan sebagai tempat penyelenggaraan kegiatan perkantoran selama jangka waktu 12 Bulan, dengan kondisi bangunan yang layak, aman, dan memenuhi standar operasional perkantoran. Pekerjaan yang dilaksanakan adalah pengadaan jasa sewa gedung kantor untuk mendukung kegiatan operasional Kantor Wilayah Kementerian HAM Kalimantan Timur. Gedung yang disewakan harus dalam kondisi siap pakai (ready to use), aman, dan memenuhi standar kelayakan bangunan untuk aktivitas perkantoran pemerintah. Penyedia wajib menjamin bahwa gedung yang disewakan memiliki legalitas yang sah, tidak dalam sengketa, dan dapat dimanfaatkan sebagai gedung perkantoran selama masa kontrak, adapun harga sewa yang disetujui merupakan harga sesuai hasil appraisal dari Penilai Publik serta ketentuan lainnya sesuai peraturan perundang-undangan yang berlaku', '• Berlokasi di wilayah Kota Samarinda atau wilayah yang memiliki aksesibilitas baik terhadap pusat pemerintahan dan pelayanan publik. • Mudah diakses kendaraan roda dua dan roda empat. • Memiliki akses jalan yang memadai dan tidak berada pada kawasan rawan bencana. • Berada pada lingkungan yang kondusif untuk kegiatan perkantoran. Standar luas ruang kerja dengan rincian sebagai berikut: a. Total luas ruang pimpinan tinggi pratama setara Eselon IIB atau yang setingkat ditetapkan maksimum 62,4 m² (enam puluh dua koma empat meter persegi); b. Total luas administrator setara Eselon III yang bukan sebagai kepala kantor ditetapkan maksimum 21 m² (dua puluh satu meter persegi); c. Total luas ruang Pejabat Fungsional Golongan III ditetapkan maksimum 11 m² (sebelas meter persegi); d. Ruang pelaksana ditetapkan maksimum 3 m² (tiga meter persegi); dan e. Ruang penunjang,', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2769761);
