INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66478904', 66478904, 'analyze_legacy', 'Kementerian Perencanaan Pembangunan Nasional', 'central', 'KANTOR MENTERI NEGARA PPN  BAPPENAS', 'JASA KONSULTAN PERANCANGAN VISUALISASI DATA DAN INFOGRAFIS KEBIJAKAN MAKAN BERGIZI GRATIS TAHUN 2026', 'Jasa Konsultansi', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 42000000, 'February 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '1 Paket', '1. Mengembangkan media komunikasi hasil kajian dan rekomendasi kebijakan yang disampaikan ke publik melalui bentuk desain infografis, konten media, dan video kegiatan 2. Mengelola dokumentasi dan komunikasi peran kedeputian PMK dalam pengawal program PSN bidang gizi, kesehatan, dan pendidikan 3. Mengelola komunikasi dengan media massa, humas Bappenas, dan K/L terkait (PCO, kemenlu, kominfo) dalam publikasi yang dibutuhkan.', '1. Pendidikan minimal S1 bidang komunikasi/ desain grafis/ marketing/ bidang lain yang relevan dibuktikan dengan ijazah 2. Memiliki pengalaman kerja minimal 2 tahun berpengalaman dalam mengelola sosial media dan media massa. Dibuktikan dengan surat keterangan kerja/ surat referensi/ kontrak kerja/ sertifikat. 3. Memiliki kemampuan dan pengalaman minimal 3 (tiga) tahun dalam membuat visualisasi data dan infografis yang efektif dan komunikatif untuk pengambilan keputusan yang dibuktikan dengan surat pengalaman kerja, 4. Memiliki kreativitas dan kemampuan dalam membuat desain konten visual yang menarik, estetik, dan artistik serta menguasai software desain (Canva, Photoshop, Illustrator, InDesign, dll) yang dibuktikan dengan hasil portofolio. 5. Memiliki pengalaman dalam strategi marketing pesan-pesan kebijakan lebih diutamakan. Dibuktikan dengan hasil desain/produk media komunikasi yang telah disusun/surat referensi 6. Memiliki pengalaman paling kurang 1 (satu) pekerjaan dalam kurun waktu 4 (empat) tahun terakhir baik di lingkungan pemerintah maupun swasta, termasuk pengalaman subkontrak. 7. Memiliki pekerjaan sejenis terkait desain/artistik/ media sosial/ graphic design, dibuktikan dengan portfolio/ surat referensi kerja/ kontrak kerja/ SK. 8. Mempunyai status valid keterangan wajib pajak berdasarkan hasil konfirmasi status wajib pajak', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2769964);
